import Int64 = require( '@stdlib/number/int64/ctor' );
import add = require( './index' );


// TESTS //

// The function returns a 64-bit signed integer...
{
	const a = new Int64( 5 );

	add( a, a ); // $ExpectType Int64
}

// The compiler throws an error if the function is provided a first argument which is not a 64-bit signed integer...
{
	const a = new Int64( 5 );

	add( true, a ); // $ExpectError
	add( false, a ); // $ExpectError
	add( null, a ); // $ExpectError
	add( undefined, a ); // $ExpectError
	add( '5', a ); // $ExpectError
	add( [], a ); // $ExpectError
	add( {}, a ); // $ExpectError
	add( ( x: number ): number => x, a ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a 64-bit signed integer...
{
	const a = new Int64( 5 );

	add( a, true ); // $ExpectError
	add( a, false ); // $ExpectError
	add( a, null ); // $ExpectError
	add( a, undefined ); // $ExpectError
	add( a, '5' ); // $ExpectError
	add( a, [] ); // $ExpectError
	add( a, {} ); // $ExpectError
	add( a, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const a = new Int64( 5 );

	add(); // $ExpectError
	add( a ); // $ExpectError
	add( a, a, a ); // $ExpectError
}

// Attached to the main export is an `assign` method which returns an array-like object containing numbers...
{
	const out = [ 0.0, 0.0 ];

	add.assign( 1, 2, 3, 4, out, 1, 0 ); // $ExpectType number[]
	add.assign( 1, 2, 3, 4, new Float64Array( 2 ), 1, 0 ); // $ExpectType Float64Array
	add.assign( 1, 2, 3, 4, new Uint32Array( 2 ), 1, 0 ); // $ExpectType Uint32Array
}

// Attached to the main export is a `strided` method which returns an array-like object containing numbers...
{
	const a = [ 1.0, 2.0 ];
	const b = [ 3.0, 4.0 ];
	const out = [ 0.0, 0.0 ];

	add.strided( a, 1, 0, b, 1, 0, out, 1, 0 ); // $ExpectType number[]
	add.strided( new Float64Array( a ), 1, 0, new Float64Array( b ), 1, 0, new Float64Array( 2 ), 1, 0 ); // $ExpectType Float64Array
	add.strided( new Uint32Array( a ), 1, 0, new Uint32Array( b ), 1, 0, new Uint32Array( 2 ), 1, 0 ); // $ExpectType Uint32Array
}
